INSERT INTO "public"."ti_chamados" ("id", "code", "title", "priority", "status", "description", "creator_name", "creator_sector", "approver_sector", "created_at", "evidence_files", "comments", "approved_by", "rejection_reason", "resolution_notes", "assigned_tech") VALUES
  ('ffefac8d-7c88-4d46-bb9b-6c4bd71d51eb', 'TI-2026-008', 'Configuração para emissão de Nf da Arthromed RN', 'alta', 'concluido', 'Solicitação de Ajuste — Faturamento Arthromed RN x Matriz PE

**Contexto da solicitação**

A Arthromed iniciou a operação de uma filial em **Natal/RN**, para a qual já foram transferidos alguns produtos e materiais da matriz em Pernambuco.

Como parte da operação, alguns materiais utilizados na filial RN precisam retornar/ser vinculados à **matriz em PE para que o faturamento seja realizado pela matriz**.

Durante esse processo, o responsável pelo estoque, Gustavo, identificou um erro ao tentar realizar a emissão da NF referente a esses produtos. O problema foi encaminhado inicialmente ao TI e, conforme orientação, estamos formalizando este chamado para que sejam realizados os ajustes necessários.

**Necessidades identificadas**

Solicitamos a análise e adequação do sistema para possibilitar o correto fluxo operacional entre a filial RN e a matriz PE, contemplando:

1. **Emissão da NF de transferência/retorno dos produtos da filial RN para a matriz PE**, permitindo que os materiais utilizados em Natal possam ser posteriormente faturados pela matriz.

2. **Criação/configuração das tabelas de preços e custos necessárias para a operação da Arthromed RN**, com foco inicial nas **tabelas de custo**, conforme alinhamento com o TI.

3. **Configuração das tributações**, que precisam ser validadas e testadas para garantir que a emissão das notas fiscais ocorra corretamente.

4. **Configuração do ACBR**, incluindo instalação e parametrização nos equipamentos da filial RN, visto que atualmente essa estrutura ainda não está disponível no local.

5. **Disponibilização das NF geradas para a contabilidade**, garantindo que a equipe contábil tenha acesso/visibilidade das notas fiscais emitidas, conforme orientação recebida do TI.

6. **Validação do fluxo completo**, realizando testes de emissão para confirmar que os processos de transferência, tributação, preços/custos e faturamento estão funcionando corretamente antes da utilização definitiva pela filial.

**Objetivo**

Garantir que a operação da **Arthromed RN** esteja devidamente parametrizada no sistema, permitindo a movimentação dos produtos entre RN e a matriz em PE e, principalmente, que os materiais utilizados na filial possam ser corretamente retornados e **faturados pela matriz**, sem inconsistências fiscais, financeiras ou contábeis.

Solicitamos, portanto, a análise do TI e a realização dos ajustes/configurações necessários para que o processo possa ser operacionalizado corretamente.', 'Adilson neto', 'Operações', 'Sem Aprovação (Direto T.I)', '2026-08-26 16:21:09.076105+00', NULL, '[{"id": "1787761822749", "text": "🛠️ Atendimento iniciado pelo técnico: Líder de Setor - T.I", "createdAt": "2026-08-26T16:30:22.749Z", "authorName": "Líder de Setor - T.I", "authorSector": "T.I"}, {"id": "1787775533309", "text": "✅ Devolutiva Técnica:\nchamado sendo encerrado, foi concluindo as configurações inicias sendo emitida a nota numero 1 pelo usuario gustavo e comunicado a Adilson e a Maria a respeito do que foi feito e solicitei a Maria que comunica-se a contabilidade da primeira emissao para que eles fiquem monitorando aparti de agora as nfs emitidas e verificando as questões fiscais como os DAE de fronteiras.", "createdAt": "2026-08-26T20:18:53.309Z", "authorName": "Líder de Setor - T.I", "authorSector": "T.I"}]', NULL, NULL, NULL, 'Líder de Setor - T.I'),
  ('5aafd3c4-e3e9-414f-a7de-60d99ac7cb23', 'TI-2026-018', 'ERRO NO SISTEMA DA ARTHROMED PE', 'critica', 'concluido', 'DESDE A NOITE DE ONTEM, O SISTEMA VEM APRESENTANDO UM BUG QUE ESTÁ REMOVENDO ALGUNS DADOS CADASTRAIS DOS ORÇAMENTOS, COMO: MÉDICO, CONVÊNIO, PARTE DO CORPO E TIPO DE CIRURGIA.

ESSES CAMPOS SÃO OBRIGATÓRIOS NO MOMENTO DA REALIZAÇÃO DOS ORÇAMENTOS E, COM A OCORRÊNCIA DO ERRO, ESTAMOS SENDO IMPOSSIBILITADOS DE PREENCHER E DAR CONTINUIDADE AO PROCESSO CORRETAMENTE.

NA MANHÃ DE HOJE, O PROBLEMA PERSISTE. DEIXO OS PRINTS ANEXADOS PARA ANÁLISE E VERIFICAÇÃO DA OCORRÊNCIA.

SOLICITO, POR GENTILEZA, A AVALIAÇÃO DO ERRO E A REGULARIZAÇÃO DO SISTEMA COM A MAIOR BREVIDADE POSSÍVEL.', 'LAHYS ARAUJO', 'Comercial interno', 'Sem Aprovação (Direto T.I)', '2026-09-03 11:37:24.218539+00', '[{"name": "WhatsApp Image 2026-09-03 at 08.29.23.jpeg", "type": "image/jpeg", "base64": ""}, {"name": "WhatsApp Image 2026-09-02 at 21.19.43.jpeg", "type": "image/jpeg", "base64": ""}]', '[{"id": "1788436681993", "text": "🛠️ Atendimento iniciado pelo técnico: Líder de Setor - T.I", "createdAt": "2026-09-03T11:58:01.993Z", "authorName": "Líder de Setor - T.I", "authorSector": "T.I"}, {"id": "1788440431380", "text": "✅ Devolutiva Técnica:\nChamado sendo encerrado, Thiago do emultec fez uma ajuste que voltou a aparecer os dados de medico e de hospital, aparentemente sendo resolvido esse problema.", "createdAt": "2026-09-03T13:00:31.380Z", "authorName": "Líder de Setor - T.I", "authorSector": "T.I"}]', NULL, NULL, NULL, 'Líder de Setor - T.I'),
  ('7c3269e4-e139-4337-9595-d0d0e262c2a6', 'TI-2026-002', 'Falha na impressão de NF', 'media', 'concluido', 'Falha na impressão do PDF da NF da Arthromed, mas na Medic funciona normalmente.', 'THACIANA', 'Comercial interno', 'Sem Aprovação (Direto T.I)', '2026-08-14 17:54:25.82198+00', '[{"name": "Captura de tela 2026-08-14 145358.png", "type": "image/png", "base64": ""}]', '[{"id": "1786730079277", "text": "aguarde", "createdAt": "2026-08-14T17:54:39.277Z", "authorName": "t_i", "authorSector": "T.I"}, {"id": "1786730486801", "text": "chamado concluido pode testar", "createdAt": "2026-08-14T18:01:26.801Z", "authorName": "t_i", "authorSector": "T.I"}, {"id": "1786730580863", "text": "✅ Devolutiva Técnica:\nproblema foi o não salvamento automatico do arquivo xml na pasta  informada no print", "createdAt": "2026-08-14T18:03:00.863Z", "authorName": "t_i", "authorSector": "T.I"}]', NULL, NULL, 'problema foi o não salvamento automatico do arquivo xml na pasta  informada no print', 't_i'),
  ('f40d55dd-5fa6-49d4-be1b-2436f4e37421', 'TI-2026-006', 'Solicitação para o GNRE', 'media', 'concluido', 'Estou desenvolvendo uma ferramenta para automatizar as emissões do GNRE e necessito que enviem uma solicitação para o GNRE para utilizar o Web services que eles disponibilizam. É necessário preencher os campos de CNPJ, Razão Social e e-mail. https://www.gnre.pe.gov.br:444/gnre/portal/automacao.jsp#', 'Gabriel', 'T.I', 'Sem Aprovação (Direto T.I)', '2026-08-25 19:08:19.816541+00', '[{"name": "Captura de tela 2026-08-25 160753.png", "type": "image/png", "base64": ""}]', '[{"id": "1787685555402", "text": "boa tarde, foi enviado os dados para eles agara vamos aguarda o retorno.", "createdAt": "2026-08-25T19:19:15.402Z", "authorName": "Líder de Setor - T.I", "authorSector": "T.I"}, {"id": "1787752045672", "text": "✅ Devolutiva Técnica:\nchamado sendo encerrado, pois precisa de uma analise tecnica, ja deixei ativo para produção na empresa arthromed pe", "createdAt": "2026-08-26T13:47:25.672Z", "authorName": "Líder de Setor - T.I", "authorSector": "T.I"}]', NULL, NULL, NULL, 'Líder de Setor - T.I'),
